export const auditCorpusEx5Draft={"summary":{"headline":"Clarify emergency offer, fix intake routing, and verify tracking for booked jobs","overview":"Joe Smolarski & Son Plumbing & Heating has strong trust assets\u2014family legacy, Master Plumber licenses, and extensive credentials\u2014but the homepage groups all services together without situational framing for emergencies or maintenance. The contact form exists but its delivery and response ownership are unverified. Multiple CTAs may confuse visitor intent, and no captured mechanism supports post-service retention. This audit prioritizes offer clarity, intake verification, and baseline measurement so the owner can turn more visitors into scheduled appointments.","biggestOpportunity":"The biggest opportunity is to turn the homepage into a situational filter: when visitors see emergency repairs, routine maintenance, and renovations separated with matching CTAs, they self-select the right path. That reduces misrouted calls, sets clearer expectations, and lets the owner measure which intent converts best once a simple inquiry log is in place.","startingPoint":"Start by testing the contact form with a staff email, confirming who replies, and verifying whether any analytics or CRM already tracks inquiries. That prevents building redundant tools and gives a foundation for every later improvement."},"business":{"offer":"Residential, commercial, and industrial plumbing, heating, remodeling, water treatment, and drain cleaning services in Browns Mills, NJ and Central New Jersey.","audience":"Homeowners, businesses, and industrial facilities in Central New Jersey needing plumbing, heating, or remodeling services.","serviceArea":"Browns Mills, NJ and surrounding Central New Jersey communities."},"findings":[{"id":"F01","category":"offer","priority":"P1","title":"Clarify emergency and maintenance positioning on the homepage","observation":"The homepage lists comprehensive services but does not explicitly frame emergency response or maintenance scheduling as distinct offerings. The captured text groups \"Sewer & Drain Cleaning\" with \"Bathroom & Kitchen Remodeling\" without situational cues that help visitors self-identify their need.","whyItMatters":"Visitors facing urgent leaks and those planning renovations have different decision timelines and risk sensitivities. Unclear positioning may force them to hunt for confirmation or call without confidence.","recommendation":"Add explicit situational headers on the homepage\u2014such as Emergency Repairs, Routine Maintenance, and Renovations\u2014grouping existing services under the scenario that matches the visitor's intent.","nextSteps":["Review the current homepage service list with the owner to confirm which services are available for same-day emergency response.","Draft situational headings and sub-bullets for the homepage using existing service names.","Replace [confirmed emergency hours] and [verified dispatch policy] placeholders with owner-confirmed details before publishing."],"effort":"low","impact":"high","confidence":"medium","citations":[{"sourceId":"S1","quote":"Residential, Commercial &amp; Industrial Complete Plumbing Services Bathroom &amp; Kitchen Remodeling Water &amp; Sewer Mains Water Treatment Systems Hydronic Heating Water Pumps, Sump Pumps &amp; Sewage Pumps Water Heaters Radiant Heating Systems Sewer &amp; Drain Cleaning Water Supply Systems Backflow Prevention Testing Backhoe &amp; Dump Truck Services Based in Browns Mills We proudly serve"},{"sourceId":"S1","quote":"Contact Us Joe Smolarski & Son Plumbing and Heating, LLC Request EstimateSchedule Service(609) 893-2784 menu | | call About Company Background Meet Our Team Credentials Testimonials Service Area Services Plumbing Services Kitchen & Bath Remodeling Hydronic Heating Water Heaters Water Conditioning & Treatment Resources FAQs Water Conservation Maintenance Tips &amp; Tricks Plumbing Code Requirements"}],"measurement":{"metric":"Homepage clarity self-assessment","howToCollect":"Ask 3-5 new callers what they believed the company specialized in before calling, record answers in a simple log.","currentBaseline":null,"successSignal":"80% or more of callers mention the service type they needed without prompting."},"copyExample":"Emergency plumbing repairs, scheduled maintenance, and kitchen and bath remodeling for Browns Mills and Central New Jersey. Call [confirmed phone] or request a [verified appointment type]."},{"id":"F02","category":"journey","priority":"P1","title":"Verify the contact form delivery and follow-up promise","observation":"The contact page states, \"complete our form and we will follow up with you,\" but the captured HTML does not reveal confirmation messaging, expected response time, or the actual delivery endpoint.","whyItMatters":"Visitors who submit a form without a clear expectation of when and how they will hear back may call again or choose another contractor.","recommendation":"Confirm the form submits successfully to a monitored inbox, add an auto-reply or on-page confirmation with a realistic follow-up timeframe, and test the full route.","nextSteps":["Submit a test form entry using a staff email address and verify the notification reaches the intended recipient.","Confirm the staff role responsible for replying to online requests and document the target response time.","Add an on-page or auto-reply message stating the confirmed follow-up window."],"effort":"low","impact":"high","confidence":"high","citations":[{"sourceId":"S2","quote":"&amp; Recommendations Portfolio Contact Contact Joe Smolarski &amp; Son Plumbing and Heating, LLC 603 Vine St Browns Mills, NJ 08015 (609) 893-2784 Contact Joe Licensed Master Plumber Email Joe Online Request Feel free to call us to schedule an appointment, or complete our form and we will follow up with you."}],"measurement":{"metric":"Form submission to staff receipt time","howToCollect":"Log timestamp of test submissions and timestamp of inbox receipt for 5 consecutive tests.","currentBaseline":null,"successSignal":"Staff receives every test submission within [verified minutes] and a responsible reply role is assigned."},"copyExample":"Thanks for contacting Joe Smolarski & Son Plumbing & Heating. We typically reply within [verified hours]. If this is urgent, please call [confirmed phone]."},{"id":"F03","category":"trust","priority":"P2","title":"Surface key credentials on high-traffic pages","observation":"The Credentials page lists extensive licenses and affiliations, but the homepage and contact page only display the general phrase \"Fully Licensed & Insured.\" Specific trust signals like Master Plumber license numbers, EPA certification, and PHCC membership are buried one click away.","whyItMatters":"Visitors scanning the homepage or deciding whether to call may not navigate to a separate credentials page. Immediate visibility of verifiable credentials reduces perceived risk.","recommendation":"Summarize the 3-4 strongest credentials on the homepage and contact page, linking to the full credentials page for detail.","nextSteps":["Select the top 3 credentials the owner wants to highlight, such as NJ Master Plumber, EPA Lead-Safe Certified, or PHCC member.","Add a compact credentials bar or bullet list to the homepage footer and contact page sidebar.","Verify displayed license numbers and expiration dates match current records before publishing."],"effort":"low","impact":"medium","confidence":"high","citations":[{"sourceId":"S5","quote":"Licenses &amp; Certifications New Jersey Plumbing License Numbers: 10705 New Jersey HVACR License Numbers: 19HC00149900 Home Improvement Contractor Certificate #13VH00881300 Universal Technician as required by 40CFR Certificate Number: 726198651710 Public Works Contractor Registration Act Certificate Number: 372051 Backflow Prevention Assembly Tester Certification Number #18269 Rinnai Registration"},{"sourceId":"S1","quote":"Central New Jersey Helpful Links Read Reviews Our Credentials View Our Work Connect with Us Fully Licensed & Insured Base Content Copyright &copy; 2026 Market Hardware, Inc."}],"measurement":{"metric":"Credential module visibility","howToCollect":"Record whether homepage and contact page display specific licenses in a simple yes/no check after update.","currentBaseline":null,"successSignal":"Both pages display at least 3 specific, current credentials with correct numbers."},"copyExample":"NJ Licensed Master Plumber #10705 \u00b7 EPA Lead-Safe Certified Firm #NAT-43291-1 \u00b7 PHCC Member"},{"id":"F04","category":"conversion","priority":"P2","title":"Distinguish \"Request Estimate\" from \"Schedule Service\" intent","observation":"The site repeatedly pairs \"Request Estimate\" and \"Schedule Service\" as adjacent options without explaining which to choose. A homeowner with a broken water heater may not know whether to request an estimate or schedule service.","whyItMatters":"Unclear CTAs can cause hesitation or misrouted inquiries, increasing back-and-forth labor and delaying booked appointments.","recommendation":"Clarify the intent behind each path\u2014e.g., \"Schedule Service\" for repairs and maintenance, \"Request Estimate\" for remodels and installations\u2014or consolidate into a single \"Book an Appointment\" flow with a brief qualifier.","nextSteps":["Confirm with the owner which services require an in-person estimate versus which can be dispatched directly.","Rewrite CTA labels or add one-line subtext beneath each button explaining when to use it.","Test the revised wording with 3 staff members to confirm it matches internal workflow."],"effort":"low","impact":"medium","confidence":"medium","citations":[{"sourceId":"S1","quote":"Contact Us Joe Smolarski & Son Plumbing and Heating, LLC Request EstimateSchedule Service(609) 893-2784 menu | | call About Company Background Meet Our Team Credentials Testimonials Service Area Services Plumbing Services Kitchen & Bath Remodeling Hydronic Heating Water Heaters Water Conditioning & Treatment Resources FAQs Water Conservation Maintenance Tips &amp; Tricks Plumbing Code Requirements"},{"sourceId":"S2","quote":"Request Estimate Schedule Service Residential, Commercial &amp; Industrial Complete Plumbing Services Bathroom &amp; Kitchen Remodeling Water &amp; Sewer Mains Water Treatment Systems Hydronic Heating Water Pumps, Sump Pumps &amp; Sewage Pumps Water Heaters Radiant Heating Systems Sewer &amp; Drain Cleaning Water Supply Systems Backflow Prevention Testing Backhoe &amp; Dump Truck Services Based in"}],"measurement":{"metric":"CTA clarity check","howToCollect":"After update, ask 5 new customers which button they would click for a repair vs. a remodel and log the responses.","currentBaseline":null,"successSignal":"4 of 5 customers select the intended path for each scenario without staff help."},"copyExample":"Schedule Service \u2014 For repairs, leaks, and maintenance calls. Request Estimate \u2014 For remodels, new installations, and larger projects."},{"id":"F05","category":"operations","priority":"P2","title":"Verify retention tools and pilot maintenance reminders","observation":"The captured pages describe services, team, and credentials, but no visible mechanism invites past customers to schedule recurring maintenance or seasonal check-ins. The owner wants to grow maintenance jobs.","whyItMatters":"Repeat maintenance work is typically higher-margin and more predictable than one-off emergency calls. Without a permission-based follow-up process, past customers may only return when a crisis occurs.","recommendation":"Verify existing customer records and communication tools, then run a small pilot sending seasonal maintenance reminders to customers who have opted in.","nextSteps":["Verify the current CRM, email tool, or customer list format with the owner.","Confirm recorded customer permission for maintenance reminders and explicitly exclude declined, withdrawn, or unverified contacts.","Draft a maintenance reminder with [verified service details] and [confirmed timing], test delivery internally, then send to the eligible pilot group."],"effort":"medium","impact":"high","confidence":"low","citations":[{"sourceId":"S1","quote":"Residential, Commercial &amp; Industrial Complete Plumbing Services Bathroom &amp; Kitchen Remodeling Water &amp; Sewer Mains Water Treatment Systems Hydronic Heating Water Pumps, Sump Pumps &amp; Sewage Pumps Water Heaters Radiant Heating Systems Sewer &amp; Drain Cleaning Water Supply Systems Backflow Prevention Testing Backhoe &amp; Dump Truck Services Based in Browns Mills We proudly serve"},{"sourceId":"S1","quote":"Central New Jersey Helpful Links Read Reviews Our Credentials View Our Work Connect with Us Fully Licensed & Insured Base Content Copyright &copy; 2026 Market Hardware, Inc."}],"measurement":{"metric":"Maintenance reminder pilot outcomes","howToCollect":"Record eligible sent count, delivery confirmations, replies, opt-outs, and resulting appointments in a 30-day window.","currentBaseline":null,"successSignal":"Pilot sends to a defined eligible cohort and logs reply and appointment counts without promising a specific conversion rate."},"copyExample":"Hi [First Name], it's Joe Smolarski & Son. Seasonal maintenance helps avoid emergency calls. If you'd like to schedule a [verified maintenance service] this [season], reply or call [confirmed phone]. Reply STOP to opt out."},{"id":"F06","category":"measurement","priority":"P1","title":"Establish inquiry-to-appointment tracking","observation":"The site offers multiple intake paths\u2014phone, estimate request, schedule service, and a contact form\u2014but no captured evidence shows how inquiries are tagged by source or linked to booked appointments.","whyItMatters":"Without linking an inquiry to its outcome, the owner cannot calculate which pages or channels produce actual jobs, making budget and prioritization decisions speculative.","recommendation":"Verify any existing analytics or CRM, then implement a minimal log that records inquiry source, date, and final appointment status for each lead.","nextSteps":["Verify existing analytics, CRM, or scheduling software with the owner before adding new tracking.","If no linked system exists, create a simple weekly log with columns for date, source, service type, and booked status.","Review the log after 4 weeks to identify the highest-volume sources."],"effort":"low","impact":"high","confidence":"medium","citations":[{"sourceId":"S1","quote":"Contact Us Joe Smolarski & Son Plumbing and Heating, LLC Request EstimateSchedule Service(609) 893-2784 menu | | call About Company Background Meet Our Team Credentials Testimonials Service Area Services Plumbing Services Kitchen & Bath Remodeling Hydronic Heating Water Heaters Water Conditioning & Treatment Resources FAQs Water Conservation Maintenance Tips &amp; Tricks Plumbing Code Requirements"},{"sourceId":"S2","quote":"&amp; Recommendations Portfolio Contact Contact Joe Smolarski &amp; Son Plumbing and Heating, LLC 603 Vine St Browns Mills, NJ 08015 (609) 893-2784 Contact Joe Licensed Master Plumber Email Joe Online Request Feel free to call us to schedule an appointment, or complete our form and we will follow up with you."}],"measurement":{"metric":"Inquiry source volume and booking status","howToCollect":"Count unique inquiries per source weekly and note which resulted in a scheduled appointment.","currentBaseline":null,"successSignal":"Owner can report total inquiries and booked jobs by source for a complete 4-week period."},"copyExample":null},{"id":"F07","category":"trust","priority":"P3","title":"Connect team story to homepage for trust","observation":"The Meet Our Team page includes family history, Master Plumber licenses, and apprenticeship details, but the homepage only mentions \"family-owned and operated quality service\" without linking to the people behind it.","whyItMatters":"For in-home services, trust in the specific technician and owner reduces stranger anxiety and can tip the decision to call.","recommendation":"Add a homepage module that introduces Joe Jr. and the team with a photo and a link to the full team page.","nextSteps":["Confirm with the owner which team members and photos are current and approved for homepage use.","Write a 2-sentence homepage snippet introducing the family legacy and link to Meet Our Team.","Verify the linked license numbers and credentials on the team page match current state records."],"effort":"low","impact":"medium","confidence":"high","citations":[{"sourceId":"S4","quote":"He worked in the industry his entire career and obtained his New Jersey Master Plumbers License on July 1st, 1978."},{"sourceId":"S1","quote":"Opinions &amp; Recommendations Portfolio Contact Request Estimate Schedule Service Joe Smolarski &amp; Son Plumbing and Heating, LLC offers a valuable combination of family-owned and operated quality service with industry leading affiliations, training, and experience."}],"measurement":{"metric":"Homepage team link presence","howToCollect":"Visual confirmation that homepage contains a team photo or \"Meet Our Team\" link.","currentBaseline":null,"successSignal":"Homepage displays a team module with current photo and link, and contact page click-through to team page is logged or confirmed via heatmap if tools exist."},"copyExample":"Meet Joe Smolarski, Jr., NJ Licensed Master Plumber, and the team serving Browns Mills since 1978. [Link to full team page]"}],"roadmap":[{"window":"30_days","objective":"Fix intake friction and verify baseline tools before making visible changes.","findingIds":["F01","F02","F03","F04","F06"],"ownerRole":"Business owner","deliverables":["[F01,F04] Business owner reviews homepage service list and confirms emergency versus estimate-required categories.","[F02] Business owner tests the contact form submission route and confirms staff reply responsibility.","[F03] Business owner selects top 3 credentials and verifies current license numbers against state records.","[F06] Business owner verifies existing analytics or starts a 4-week inquiry source and booking log."]},{"window":"60_days","objective":"Launch trust improvements and a permission-based retention pilot.","findingIds":["F03","F05","F07"],"ownerRole":"Business owner","deliverables":["[F03,F07] Business owner publishes homepage credentials bar and team module with current photos and links.","[F05] Business owner verifies customer contact permission and excludes opted-out or unverified contacts.","[F05] Business owner drafts maintenance reminder, tests delivery internally, and sends to eligible pilot group."]},{"window":"90_days","objective":"Measure results and refine offers and CTAs based on collected data.","findingIds":["F01","F04","F05","F06"],"ownerRole":"Business owner","deliverables":["[F06] Business owner reviews 4-week inquiry log to identify top booking sources and conversion patterns.","[F01,F04] Business owner updates CTA labels based on customer clarity feedback and confirmed service workflows.","[F05] Business owner logs pilot delivery, replies, opt-outs, and resulting appointments in a defined 30-day window."]}],"unknowns":["Whether the contact form successfully delivers to a monitored inbox and who is responsible for replies.","Whether the business currently uses a CRM, email marketing tool, or customer database for follow-up.","Whether customer contact permissions for maintenance reminders are recorded and how opt-outs are tracked.","Current weekly volume of website form inquiries versus phone calls and how sources are currently tagged.","Whether displayed team photos, credentials, and license numbers are fully current and accurate.","How internal staff distinguish between emergency dispatch calls and estimate requests during intake."],"questionsToResolve":["Which specific services does the owner classify as same-day emergency versus scheduled estimate jobs?","What is the current staff role responsible for responding to online form submissions and what is the actual response time?","Does the owner have recorded customer consent for email or text maintenance reminders, and in what format?","What existing software, if any, is used for scheduling, CRM, analytics, or email tracking?","How many inquiries per week currently come through the website form versus the phone number?"]};

